"""Exact integer range sums, compared with bounded CPython results."""

def indexed_range():
    events = []
    class Index:
        def __init__(self, value): self.value = value
        def __index__(self):
            events.append(self.value)
            return self.value
    return sum(range(Index(-4), Index(20), Index(3))), events

def custom_start():
    events = []
    class Total:
        def __add__(self, value):
            events.append(value)
            return self
    initial = Total()
    result = sum(range(-3, 9, 2), initial)
    return result is initial, events

def integer_start_override():
    events = []
    class Total(int):
        def __add__(self, value):
            events.append(value)
            return Total(int(self) + value)
    result = sum(range(3, 19, 3), Total(100))
    return type(result).__name__, int(result), events

def empty_identity():
    starts = [True, False, 2**200, object(), -0.0]
    return [sum(range(10, 0), start) is start for start in starts]

