for name, call, expected in CASES:
    try:
        value = call()
        actual = ('ok', type(value).__name__, repr(value))
    except Exception as error:
        actual = ('err', type(error).__name__, str(error))
    assert actual == expected, (name, actual, expected)

# Empty exact integer starts preserve identity. Floating-point identity remains
# a separately recorded difference in the release oracle.
for start in (True, False, 2**200, object()):
    assert sum(range(10, 0), start) is start
print('ok')
